 let wallet=createWalletSend(walletOptions),tail=Promise.resolve();const deposit=vi.fn(async()=>noteResult),checkNote=vi.fn(async()=>noteResult);
 const deps={identityDigest:checkoutOwner,assertCurrent(){if(!current)throw Error('identity changed');},walletSend:async()=>wallet,notes:{validate:vi.fn(async()=>{}),inspect:vi.fn(async()=>note),deposit,check:checkNote},readWallet:async()=>({userId:checkoutSender,totalUsdCents:String(balance),reserveUsdCents:String(balance),settlementUsdCents:'0',balancePhiMicro:'10000000',projectionComplete:true,portfolioUsdCents:null,pnlUsdCents:null,withdrawableUsdCents:null,pulse:null,kaiUpulse:null}as SharedWallet),store:{read:async()=>structuredClone(state),write},lock:async<T,>(work:()=>Promise<T>)=>{const prior=tail;let release!:()=>void;tail=new Promise(resolve=>release=resolve);await prior;try{return await work();}finally{release();}}};
 return{deps:{...deps,note},transfer,begin,deposit,write,request,newController(){wallet=createWalletSend(walletOptions);return createHostedCheckout(deps);},get state(){return state;},setBalance(value:number){balance=value;},expireCard(){cardExpired=true;},creditCard(){if(!cardPaid)balance+=1000;cardPaid=true;},confirmNote(){if(noteResult.status!=='confirmed')balance+=1000;noteResult={...note,status:'confirmed',creditSourceDigest:'c'.repeat(64)};},loseLookup(value:boolean){lookupMissing=value;},interruptNoteSave(){failNoteSave=true;},changeIdentity(){current=false;}};
